-- Business Launch Center: draft entries for the 50 states and D.C. (founder directive 31), prepared by Peace on 2026-11-27.
-- Sources: official state pages, gathered through searches limited to official domains (the session's network could not load the
-- pages directly), so every entry stays a DRAFT and lists its uncertain points. Members see official links for every state; fee
-- and annual-report figures appear only after the owner reviews and approves each state.
insert into public.formation_jurisdictions (code, name, filing_office, filing_office_url, business_name_search_url, online_filing_url, business_license_url,
  revenue_department_url, llc, corporation, nonprofit, registered_agent, sources, uncertain, verified_on, review_by, status) values
  ('AK', 'Alaska', 'Alaska Dept. of Commerce, Community, and Economic Development - Division of Corporations, Business and Professional Licensing (Corporations Section)', 'https://www.commerce.alaska.gov/web/cbpl/corporations', 'https://www.commerce.alaska.gov/cbp/main/', null, 'https://www.commerce.alaska.gov/web/cbpl/BusinessLicensing/NewBLOnline.aspx', null, $j${"document": "Articles of Organization", "filing_fee_usd": 250, "fee_notes": "$250 nonrefundable. Initial report (free) due within six months of formation.", "annual_report": {"name": "Biennial Report", "fee_usd": 100, "frequency": "biennial (even/odd year matching formation year)", "due": "Due January 2; may file from October 2 of prior year; late fee after February 1 ($137.50 total with late fee)"}, "tax_notes": "No state franchise tax. Separate Alaska business license required ($50/yr or $100/2 yrs)."}$j$::jsonb, $j${"document": "Articles of Incorporation", "filing_fee_usd": 250, "fee_notes": "$250 (form 08-400).", "annual_report": {"name": "Biennial Report", "fee_usd": 100, "frequency": "biennial", "due": "Due January 2; late after February 1"}, "tax_notes": "Alaska business license also required."}$j$::jsonb, $j${"document": "Articles of Incorporation (Nonprofit)", "filing_fee_usd": 50, "fee_notes": "$50 (form 08-438). Initial report free within six months.", "annual_report": {"name": "Biennial Report", "fee_usd": 25, "frequency": "biennial", "due": "Due July 2 (file from April 2); $5 late fee on/after August 2"}, "tax_notes": null}$j$::jsonb, 'Must continuously maintain a registered agent with a physical street address in the state (no P.O. box); an individual resident (including an owner) or an authorized business entity may serve.', $j$[{"url": "https://www.commerce.alaska.gov/web/cbpl/Corporations/CorporationFormsFees", "title": "Alaska Corporation Forms & Fees"}, {"url": "https://www.commerce.alaska.gov/web/cbpl/Corporations/BiennialReportsFAQs", "title": "Alaska Biennial Reports FAQs"}, {"url": "https://www.commerce.alaska.gov/web/cbpl/Corporations/BiennialReports", "title": "Alaska Biennial Reports"}, {"url": "https://www.commerce.alaska.gov/web/cbpl/BusinessLicensing/BusinessLicensingFormsFees", "title": "Alaska Business Licensing Forms & Fees"}, {"url": "https://www.commerce.alaska.gov/web/cbpl/BusinessLicensing/NewBLOnline.aspx", "title": "Alaska New Business License Online"}, {"url": "https://www.commerce.alaska.gov/cbp/main/", "title": "Alaska Business Search"}]$j$::jsonb, $j$["Gathered from official-domain search results on 2026-11-27; confirm each figure on the official page before approving.", "Official state hosts were blocked by this session's network proxy; values come from official-domain pages as indexed and excerpted by search (domain-restricted search), not direct page fetches.", "online_filing_url not confirmed", "Corporation biennial report fee ($100 domestic) inferred from LLC figure/FAQ; corporate late-fee amount conflicts between statute and FAQ", "revenue_department_url (Alaska Dept. of Revenue Tax Division) not confirmed", "Registered agent summary not verified on an official page"]$j$::jsonb, '2026-11-27', '2027-05-27', 'draft'),
  ('AL', 'Alabama', 'Alabama Secretary of State, Business Entities Division', 'https://www.sos.alabama.gov/business-entities/llcs', 'https://arc-sos.state.al.us/CGI/CORPNAME.MBR/INPUT', null, 'https://www.sos.alabama.gov/business-entities/start-business', 'https://www.revenue.alabama.gov/sales-use/business-tax-online-registration-system/', $j${"document": "Certificate of Formation (Domestic LLC)", "filing_fee_usd": 200, "fee_notes": "$200 state filing fee per current SOS fee schedule and 2026 form. Name reservation required before filing (separate fee). Credit card payments carry a convenience fee of 3% + $2.00 per the form. Older probate-route forms showing $100 are outdated.", "annual_report": {"name": "Business Privilege Tax Return (filed with Alabama Dept. of Revenue); no SOS annual report for LLCs since 2024", "fee_usd": 50, "frequency": "annual", "due": "LLEs/S-corps: 15th day of 3rd month after start of taxable year (per ADOR due-date table)"}, "tax_notes": "Alabama Business Privilege Tax applies; $50 minimum for LLEs/disregarded entities (tax years after 2022). Filed with ADOR."}$j$::jsonb, $j${"document": "Certificate of Formation (Domestic Corporation)", "filing_fee_usd": 200, "fee_notes": "$200 per SOS fee schedule (Ala. Code 10A-1-4.31). Name reservation required. Card convenience fee applies.", "annual_report": {"name": "Annual Report (filed with SOS Business Services Division beginning 2024)", "fee_usd": 10, "frequency": "annual", "due": "Filed with SOS; privilege tax return due with federal return for C-corps (15th day of 4th month for calendar year)"}, "tax_notes": "Business Privilege Tax filed with ADOR (Form CPT); minimum generally $100, or $50 where tax would be $100 for tax years after 2022."}$j$::jsonb, $j${"document": "Certificate of Formation (Domestic Nonprofit Corporation)", "filing_fee_usd": 200, "fee_notes": "Fee schedule lists the same $200 Certificate of Formation fee for nonprofits.", "annual_report": {"name": "None (SOS annual report required only of for-profit and professional corporations per ADOR 2024 notice)", "fee_usd": null, "frequency": null, "due": null}, "tax_notes": null}$j$::jsonb, 'Must continuously maintain a registered agent with a physical street address in the state (no P.O. box); an individual resident (including an owner) or an authorized business entity may serve.', $j$[{"url": "https://www.sos.alabama.gov/business-entities/llcs", "title": "Alabama SOS - LLCs"}, {"url": "https://www.sos.alabama.gov/sites/default/files/form-files/FeeSchedule.pdf", "title": "Alabama SOS Business Entities Fee Schedule"}, {"url": "https://www.sos.alabama.gov/sites/default/files/2026-03/DomesticLLCFormation.pdf", "title": "Alabama Domestic LLC Certificate of Formation form (2026)"}, {"url": "https://www.revenue.alabama.gov/tax-types/business-privilege-tax/", "title": "ADOR - Business Privilege Tax"}, {"url": "https://www.revenue.alabama.gov/notice-important-changes-to-the-2024-business-privilege-tax-filing-requirements/", "title": "ADOR - 2024 BPT filing changes notice"}, {"url": "https://www.revenue.alabama.gov/individual-corporate/due-dates/", "title": "ADOR - Due Dates"}, {"url": "https://arc-sos.state.al.us/CGI/CORPNAME.MBR/INPUT", "title": "Alabama SOS Business Entity Search"}, {"url": "https://www.revenue.alabama.gov/sales-use/business-tax-online-registration-system/", "title": "ADOR - Business Tax Online Registration System"}]$j$::jsonb, $j$["Gathered from official-domain search results on 2026-11-27; confirm each figure on the official page before approving.", "Official state hosts were blocked by this session's network proxy; values come from official-domain pages as indexed and excerpted by search (domain-restricted search), not direct page fetches.", "online_filing_url: SOS says Certificate of Formation can be filed online but the portal URL was not confirmed", "Name reservation fee amount not confirmed", "Exact SOS corporate annual report due date (post-2024) not confirmed", "Registered agent summary not verified on an official page", "business_license_url is the SOS 'How to Start a Business' page; Alabama has no single state general business license portal confirmed"]$j$::jsonb, '2026-11-27', '2027-05-27', 'draft'),
  ('AR', 'Arkansas', 'Arkansas Secretary of State, Business & Commercial Services', 'https://www.sos.arkansas.gov/business-commercial-services-bcs/forms-fees/llc', 'https://www.sos.arkansas.gov/business-commercial-services-bcs/for-current-businesses', null, null, 'https://www.dfa.arkansas.gov/online-services/taxpayers/', $j${"document": "Certificate of Organization (Form LL-01)", "filing_fee_usd": 50, "fee_notes": "$50 paper; $45 online per SOS LLC fee table.", "annual_report": {"name": "Annual LLC Franchise Tax Report", "fee_usd": 150, "frequency": "annual", "due": "On or before May 1 of the year following formation and each year after; $25 late penalty plus interest"}, "tax_notes": "$150 annual franchise tax for all LLCs (filed with SOS)."}$j$::jsonb, $j${"document": "Articles of Incorporation (Form DN-01)", "filing_fee_usd": 50, "fee_notes": "$50 paper; $45 online.", "annual_report": {"name": "Annual Corporation Franchise Tax Report", "fee_usd": 150, "frequency": "annual", "due": "May 1"}, "tax_notes": "Franchise tax minimum $150 for corporations with stock (calculated on capital stock); $300 minimum noted for corporations without stock (per SOS forms page)."}$j$::jsonb, $j${"document": "Articles of Incorporation - Nonprofit (Form NPD-1)", "filing_fee_usd": 50, "fee_notes": "$50 paper; $45 online.", "annual_report": {"name": "Annual Nonprofit Corporation Disclosure Statement", "fee_usd": null, "frequency": "annual", "due": null}, "tax_notes": null}$j$::jsonb, 'Form LL-01 requires naming a registered agent with a physical Arkansas address. Agent change filed online (DO-03) has no fee. Must continuously maintain a registered agent with a physical street address in the state (no P.O. box); an individual resident (including an owner) or an authorized business entity may serve.', $j$[{"url": "https://www.sos.arkansas.gov/business-commercial-services-bcs/forms-fees/llc", "title": "Arkansas SOS - LLC Forms/Fees"}, {"url": "https://www.sos.arkansas.gov/business-commercial-services-bcs/forms-fees/corporations", "title": "Arkansas SOS - Corporation Forms/Fees"}, {"url": "https://www.sos.arkansas.gov/business-commercial-services-bcs/franchise-tax-report-forms/", "title": "Arkansas SOS - Franchise Tax Report Forms"}, {"url": "https://www.sos.arkansas.gov/uploads/bcs/LLC1_FT_2026.pdf", "title": "Annual LLC Franchise Tax Report 2026"}, {"url": "https://www.sos.arkansas.gov/uploads/bcs/LL-01.pdf", "title": "Form LL-01 Certificate of Organization"}, {"url": "https://www.sos.arkansas.gov/business-commercial-services-bcs/for-current-businesses", "title": "Arkansas SOS - Current Businesses"}, {"url": "https://www.dfa.arkansas.gov/online-services/taxpayers/", "title": "Arkansas DFA - Taxpayers (ATAP)"}]$j$::jsonb, $j$["Gathered from official-domain search results on 2026-11-27; confirm each figure on the official page before approving.", "Official state hosts were blocked by this session's network proxy; values come from official-domain pages as indexed and excerpted by search (domain-restricted search), not direct page fetches.", "LLC $45 online fee appears only in SOS LLC fee table (older schedule shows $50 only)", "Nonprofit annual disclosure statement fee not confirmed", "Corporation no-stock $300 minimum franchise tax not directly confirmed", "online_filing_url not confirmed; business_name_search_url is the SOS page that links to the entity search", "No state general business license portal confirmed"]$j$::jsonb, '2026-11-27', '2027-05-27', 'draft'),
  ('AZ', 'Arizona', 'Arizona Corporation Commission, Corporations Division', 'https://azcc.gov/faqs/BusinessServicesFAQs', 'https://ecorp.azcc.gov/EntitySearch/Index', 'https://ecorp.azcc.gov/', null, 'https://www.aztaxes.gov/Home/WelcomeRegister', $j${"document": "Articles of Organization (Form L010)", "filing_fee_usd": 50, "fee_notes": "$50 regular; expedited processing +$35 ($85). ACC FAQ references $85 online, which matches the expedited total.", "annual_report": {"name": "None - LLCs do not file annual reports", "fee_usd": null, "frequency": null, "due": null}, "tax_notes": "Publication of notice required after approval (A.R.S. 29-3201); approval letter explains how. Publication rules for Maricopa/Pima County addresses not confirmed."}$j$::jsonb, $j${"document": "Articles of Incorporation (For-Profit, Form C010)", "filing_fee_usd": 60, "fee_notes": "$60 regular; expedite +$35.", "annual_report": {"name": "Annual Report", "fee_usd": 45, "frequency": "annual", "due": "Each corporation has its own due date (see entity record); may file up to 90 days early; 6-month extension available"}, "tax_notes": "Publication required after approval (statute cited in instructions)."}$j$::jsonb, $j${"document": "Articles of Incorporation (Nonprofit, Form C011)", "filing_fee_usd": 40, "fee_notes": "$40 regular; expedite +$35.", "annual_report": {"name": "Annual Report", "fee_usd": 10, "frequency": "annual", "due": "Entity-specific due date"}, "tax_notes": "Publication required (A.R.S. 10-3203)."}$j$::jsonb, 'Arizona requires a ''statutory agent'' with an Arizona physical address; Must continuously maintain a registered agent with a physical street address in the state (no P.O. box); an individual resident (including an owner) or an authorized business entity may serve.', $j$[{"url": "https://azcc.gov/docs/default-source/corps-files/fee-schedules/fee-schedule-llcs.pdf", "title": "ACC Schedule of Fees - LLCs"}, {"url": "https://azcc.gov/docs/default-source/corps-files/instructions/l010i-instructions-articles-of-organization.pdf", "title": "ACC L010i Instructions - Articles of Organization"}, {"url": "https://azcc.gov/docs/default-source/corps-files/forms/c010-articles-of-incorporation-for-profit.pdf", "title": "ACC Articles of Incorporation - For Profit"}, {"url": "https://www.azcc.gov/docs/default-source/corps-files/forms/c011-articles-of-incorporation-nonprofit.pdf", "title": "ACC Articles of Incorporation - Nonprofit"}, {"url": "https://www.azcc.gov/docs/default-source/corps-files/instructions/c011i-instructions-articles-of-inc-nonprofit.pdf", "title": "ACC C011i Instructions"}, {"url": "https://azcc.gov/faqs/BusinessServicesFAQs", "title": "ACC Business Services FAQs"}, {"url": "https://www.azcc.gov/docs/default-source/corps-files/instructions/c002i-instructions-ar-extension-request.pdf", "title": "ACC Annual Report Extension Instructions"}, {"url": "https://www.aztaxes.gov/Home/WelcomeRegister", "title": "AZTaxes - Register"}]$j$::jsonb, $j$["Gathered from official-domain search results on 2026-11-27; confirm each figure on the official page before approving.", "Official state hosts were blocked by this session's network proxy; values come from official-domain pages as indexed and excerpted by search (domain-restricted search), not direct page fetches.", "Whether publication is waived for Maricopa/Pima County entities (ACC self-publication) not confirmed", "Whether $85 online LLC price is standard or expedited total", "business_name_search_url/online_filing_url: production eCorp URL inferred from ACC test-site and document links (ecorptestonline.azcc.gov / ecorp.azcc.gov)", "No statewide general business license portal confirmed", "Registered agent summary not verified on an official page"]$j$::jsonb, '2026-11-27', '2027-05-27', 'draft'),
  ('CA', 'California', 'California Secretary of State, Business Programs Division (Business Entities)', 'https://www.sos.ca.gov/business-programs', 'https://bizfileonline.sos.ca.gov/search/business', 'https://bizfileonline.sos.ca.gov/', null, 'https://temp.cdtfa.ca.gov/services/registration.htm', $j${"document": "Articles of Organization (Form LLC-1)", "filing_fee_usd": 70, "fee_notes": "$70 (Gov. Code 12190). $15 handling fee only for in-person paper filings; certified copy $5.", "annual_report": {"name": "Statement of Information (LLC-12)", "fee_usd": 20, "frequency": "biennial", "due": "Initial within 90 days of formation, then every two years during the applicable filing period"}, "tax_notes": "$800 annual LLC tax (FTB) for every LLC organized or registered; the AB 85 first-year exemption covered only LLCs formed 2021-2023. LLC fee also applies when gross receipts >= $250,000."}$j$::jsonb, $j${"document": "Articles of Incorporation (General Stock)", "filing_fee_usd": 100, "fee_notes": "$100 filing fee; $15 in-person handling fee; $5 certified copy.", "annual_report": {"name": "Statement of Information", "fee_usd": 25, "frequency": "annual", "due": "Initial within 90 days, then annually during filing period"}, "tax_notes": "$800 minimum franchise tax (FTB); waived for a new corporation's first taxable year."}$j$::jsonb, $j${"document": "Articles of Incorporation (Nonprofit Public Benefit / Mutual Benefit / Religious)", "filing_fee_usd": 30, "fee_notes": "$30 filing fee; $15 in-person handling; $5 certified copy.", "annual_report": {"name": "Statement of Information", "fee_usd": 20, "frequency": "biennial", "due": "Every two years"}, "tax_notes": "Exempt status must be obtained separately from FTB."}$j$::jsonb, 'California calls it ''agent for service of process'': an individual resident with a California street address or a registered corporate agent (CA Corp. Code 1505). Must continuously maintain a registered agent with a physical street address in the state (no P.O. box); an individual resident (including an owner) or an authorized business entity may serve.', $j$[{"url": "https://www.sos.ca.gov/business-programs/cannabizfile/cannabis-forms-and-fees/limited-liability-companies-llc-california", "title": "CA SOS - LLC forms and fees"}, {"url": "https://bpd.cdn.sos.ca.gov/bizfile/bizfile-brochure.pdf", "title": "CA SOS - Starting a New Business in California (bizfile brochure)"}, {"url": "https://www.sos.ca.gov/business-programs/business-entities/faqs", "title": "CA SOS - Business Entities FAQs"}, {"url": "https://www.ftb.ca.gov/forms/misc/3556.html", "title": "FTB Pub. 3556 LLC Filing Information"}, {"url": "https://www.ftb.ca.gov/forms/misc/1123.html", "title": "FTB Pub. 1123 Guide to Common Forms of Ownership"}, {"url": "https://www.ftb.ca.gov/forms/2025/2025-3522.pdf", "title": "FTB 3522 Instructions 2025"}, {"url": "https://www.sos.ca.gov/business-programs/bizfile", "title": "CA SOS - bizfile"}, {"url": "https://temp.cdtfa.ca.gov/services/registration.htm", "title": "CDTFA Online Services - Registration"}]$j$::jsonb, $j$["Gathered from official-domain search results on 2026-11-27; confirm each figure on the official page before approving.", "Official state hosts were blocked by this session's network proxy; values come from official-domain pages as indexed and excerpted by search (domain-restricted search), not direct page fetches.", "Statement of Information fee split ($25 corporations vs $20 LLC/nonprofit) - SOS FAQ says '$20 or $25' without per-entity mapping in excerpt", "Whether any post-2023 first-year $800 LLC exemption exists not confirmed", "business_name_search_url path (/search/business) inferred from bizfile Online; base portal confirmed", "revenue_department_url host 'temp.cdtfa.ca.gov' as indexed; main site is cdtfa.ca.gov", "CalGold permit portal not confirmed", "Registered agent summary not verified on an official page"]$j$::jsonb, '2026-11-27', '2027-05-27', 'draft'),
  ('CO', 'Colorado', 'Colorado Secretary of State, Business Division', 'https://www.coloradosos.gov/pubs/business/fileAForm.html', 'https://www.coloradosos.gov/biz/BusinessEntityCriteriaExt.do', 'https://www.sos.state.co.us/pubs/business/fileAForm.html', 'https://mybiz.colorado.gov/intro', 'https://tax.colorado.gov/new-businesses', $j${"document": "Articles of Organization", "filing_fee_usd": 50, "fee_notes": "$50, online filing only.", "annual_report": {"name": "Periodic Report", "fee_usd": 25, "frequency": "annual", "due": "Due around the anniversary month of formation; $50 late penalty"}, "tax_notes": "No state franchise tax on LLCs."}$j$::jsonb, $j${"document": "Articles of Incorporation (Profit Corporation)", "filing_fee_usd": 50, "fee_notes": "$50, online only (no paper form).", "annual_report": {"name": "Periodic Report", "fee_usd": 25, "frequency": "annual", "due": "Anniversary-month window; $50 late penalty"}, "tax_notes": null}$j$::jsonb, $j${"document": "Articles of Incorporation (Nonprofit Corporation)", "filing_fee_usd": 50, "fee_notes": "$50, online only.", "annual_report": {"name": "Periodic Report", "fee_usd": 25, "frequency": "annual", "due": "Anniversary-month window"}, "tax_notes": null}$j$::jsonb, 'Registered agent must reside in (or be authorized to do business in) Colorado with a Colorado street address; the entity or an individual owner may serve (per SOS checklist).', $j$[{"url": "https://www.sos.state.co.us/pubs/info_center/fees/business.html", "title": "Colorado SOS - Business Organizations Fee Schedule"}, {"url": "https://coloradosos.gov/pubs/newsRoom/pressReleases/2024/PR20240617Fees.html", "title": "Colorado SOS press release on fee changes (2024)"}, {"url": "https://www.sos.state.co.us/pubs/business/FAQs/reports.html", "title": "Colorado SOS - Periodic reports FAQ"}, {"url": "https://www.coloradosos.gov/pubs/business/helpFiles/ProfitCorpChecklist.pdf", "title": "Colorado SOS - Profit Corporation checklist"}, {"url": "https://www.sos.state.co.us/pubs/business/forms_main.html", "title": "Colorado SOS - Business Forms List"}, {"url": "https://www.coloradosos.gov/biz/BusinessEntityCriteriaExt.do", "title": "Colorado SOS - Business Database Search"}, {"url": "https://mybiz.colorado.gov/intro", "title": "MyBizColorado"}, {"url": "https://tax.colorado.gov/new-businesses", "title": "Colorado DOR - Getting Your Business Started"}]$j$::jsonb, $j$["Gathered from official-domain search results on 2026-11-27; confirm each figure on the official page before approving.", "Official state hosts were blocked by this session's network proxy; values come from official-domain pages as indexed and excerpted by search (domain-restricted search), not direct page fetches.", "Exact periodic report filing window rule (months around anniversary) not confirmed", "LLC Articles of Organization $50 confirmed via search summary of fee schedule, not direct fetch"]$j$::jsonb, '2026-11-27', '2027-05-27', 'draft'),
