  ('NE', 'Nebraska', 'Nebraska Secretary of State, Business Services Division', 'https://sos.nebraska.gov/business-services/corporate-and-business', 'https://www.nebraska.gov/sos/corp/corpsearch.cgi', 'https://sos.nebraska.gov/business-services/corporate-and-business', null, 'https://revenue.nebraska.gov/', $j${"document": "Certificate of Organization", "filing_fee_usd": 100, "fee_notes": "$100 online / $110 in-office (fees effective 7/1/2021); portal fees apply online. Note: SOS announced transition to a new entity search/filing system expected December 7, 2026.", "annual_report": {"name": "Biennial Report", "fee_usd": 30, "frequency": "biennial", "due": "Odd-numbered years (due date not confirmed)"}, "tax_notes": "Publication required: notice of organization must be published in a legal newspaper for three successive weeks and proof of publication filed with the Secretary of State (Neb. Rev. Stat. 21-193). Pending bills (LB 40, LB 1014) to change this not confirmed enacted."}$j$::jsonb, $j${"document": "Articles of Incorporation", "filing_fee_usd": 100, "fee_notes": "$100 online / $110 in-office per 2021 fee notice for initial business entity filings; forms table also shows other figures.", "annual_report": {"name": "Biennial Report", "fee_usd": null, "frequency": "biennial", "due": "Even-numbered years (due date not confirmed)"}, "tax_notes": "Publication of notice of incorporation also required for corporations (not confirmed this session)."}$j$::jsonb, $j${"document": "Articles of Incorporation (Nonprofit)", "filing_fee_usd": 25, "fee_notes": "$25 online / $30 in-office.", "annual_report": {"name": "Biennial Report", "fee_usd": 25, "frequency": "biennial", "due": "Odd-numbered years; $25 online plus min. $3 portal fee (reinstatement form shows $30)"}, "tax_notes": null}$j$::jsonb, 'Must continuously maintain a registered agent with a physical street address in the state (no P.O. box); an individual resident (including an owner) or an authorized entity may serve