  ('NY', 'New York', 'New York Department of State, Division of Corporations', 'https://dos.ny.gov/corporations-state-records-and-ucc', 'https://dos.ny.gov/corporation-and-business-entity-search-database', 'https://www.businessexpress.ny.gov/', 'https://www.businessexpress.ny.gov/', 'https://www.tax.ny.gov/', $j${"document": "Articles of Organization (DOS 1336)", "filing_fee_usd": 200, "fee_notes": "$200. Certificate of Publication filing fee $50 (separate). Expedite fees available (not confirmed).", "annual_report": {"name": "Biennial Statement", "fee_usd": 9, "frequency": "biennial", "due": "Every two years in the calendar month of original filing"}, "tax_notes": "Publication required (LLC Law 206): publish in two county-clerk-designated newspapers for six consecutive weeks within 120 days of formation, then file Certificate of Publication ($50) or authority is suspended. Annual LLC filing fee to NY Department of Taxation (Form IT-204-LL): $25 minimum, tiered up to $4,500 by NY-source gross income."}$j$::jsonb, $j${"document": "Certificate of Incorporation", "filing_fee_usd": 125, "fee_notes": "$125 filing fee; organization tax on authorized shares (minimum $10) also payable to DOS (not confirmed this session).", "annual_report": {"name": "Biennial Statement", "fee_usd": 9, "frequency": "biennial", "due": "Every two years in the calendar month of original filing"}, "tax_notes": "Subject to NY corporation franchise tax (Department of Taxation and Finance)."}$j$::jsonb, $j${"document": "Certificate of Incorporation (Not-for-Profit)", "filing_fee_usd": 75, "fee_notes": "$75.", "annual_report": {"name": "None (biennial statement not required for not-for-profit corporations)", "fee_usd": null, "frequency": "none", "due": "Charities may have separate Attorney General Charities Bureau annual filings"}, "tax_notes": null}$j$::jsonb, 'Must designate the Secretary of State as agent for service of process; a separate registered agent with NY address is optional.', $j$[{"url"