  ('OH', 'Ohio', 'Ohio Secretary of State - Business Services', 'https://www.ohiosos.gov/business', 'https://businesssearch.ohiosos.gov/', 'https://bsportal.ohiosos.gov/', null, 'https://tax.ohio.gov/business/commercial-activity-tax', $j${"document": "Articles of Organization (Form 610)", "filing_fee_usd": 99, "fee_notes": "$99 base (ORC 111.16(F)). Expedite options extra, e.g., Expedited 1 = +$100 (2 business days). Name reservation $39.", "annual_report": {"name": "None (no periodic report to SOS)", "fee_usd": null, "frequency": "none", "due": null}, "tax_notes": "Commercial Activity Tax (CAT) applies to LLCs regardless of form once Ohio taxable gross receipts exceed $6 million (tax year 2025+); register within 30 days via Ohio Business Gateway; quarterly filing."}$j$::jsonb, $j${"document": "Articles of Incorporation (Form 532A, for-profit)", "filing_fee_usd": 99, "fee_notes": "SOS fee schedule lists $99. ORC 111.16 ties the flat $99 to corporations without authorized shares; share-based formula (Ohio Shares Calculator) applies for stock corporations, so authorized-share count can raise the fee.", "annual_report": {"name": "None (no periodic report to SOS)", "fee_usd": null, "frequency": "none", "due": null}, "tax_notes": "Subject to CAT on Ohio taxable gross receipts above $6 million."}$j$::jsonb, $j${"document": "Articles of Incorporation - Nonprofit (Form 532B)", "filing_fee_usd": 99, "fee_notes": "$99 flat; name reservation $39.", "annual_report": {"name": "Statement of Continued Existence (Form 522)", "fee_usd": 25, "frequency": "every 5 years", "due": "Every five years; SOS mails reminder to statutory agent ~4 months before deadline; failure cancels charter (reinstatement Form 525B, $25)"}, "tax_notes": "None identified."}$j$::jsonb, 'Every entity must appoint and maintain a statutory agent: an Ohio-resident individual or a business entity authorized to do business in Ohio with an Ohio street address. No P.O. boxes (unless with rural route) and no CMRA addresses. No fee for original appointment.', $j$[{"url": "https://www.ohiosos.gov/businesses/filing-forms--fee-schedule/", "title": "Ohio SOS - Business Filing Forms & Fee Schedule"}, {"url": "https://codes.ohio.gov/ohio-revised-code/section-111.16", "title": "Ohio Revised Code 111.16 (SOS fees)"}, {"url": "https://www.ohiosos.gov/assets/business-start-a-llc.pdf", "title": "Ohio SOS - Start a Limited Liability Company in Ohio"}, {"url": "https://www.ohiosos.gov/assets/business-start-a-nonprofit.pdf", "title": "Ohio SOS - Start a Nonprofit Organization in Ohio"}, {"url": "https://www.ohiosos.gov/business/ohio-business-roadmap/frequently-asked-questions", "title": "Ohio SOS - Ohio Business FAQ"}, {"url": "https://codes.ohio.gov/ohio-revised-code/section-1782.04", "title": "ORC 1782.04 (statutory agent)"}, {"url": "https://businesssearch.ohiosos.gov/", "title": "Ohio SOS Business Search"}, {"url": "https://bsportal.ohiosos.gov/", "title": "Ohio Business Central"}, {"url": "https://tax.ohio.gov/business/commercial-activity-tax", "title": "Ohio Department of Taxation - Commercial Activity Tax"}]$j$::jsonb, $j$["Gathered from official-domain search results on 2026-11-27; confirm each figure on the official page before approving.", "Absence of an annual report for Ohio LLCs/for-profit corporations not stated verbatim on an extracted official page (consistent with fee schedule, which lists none).", "For-profit corporation fee may exceed $99 depending on authorized shares (share-based formula); exact formula not extracted.", "No statewide general business license portal identified; business_license_url left null.", "Ohio Department of Taxation general business-registration landing page not confirmed; CAT page used.", "Method caveat: this session's network policy blocked direct HTTP access to all state sites; facts were taken from search-index extracts of the official-domain pages listed in sources (search restricted to official domains), not from a live page load."]$j$::jsonb, 