  ('OK', 'Oklahoma', 'Oklahoma Secretary of State - Business Services', 'https://oklahoma.gov/sos/businesses/business-services.html', 'https://business.sos.ok.gov/', 'https://business.sos.ok.gov/', 'https://oklahoma.gov/business/launch/register-your-business.html', 'https://oklahoma.gov/tax/helpcenter/businesses.html', $j${"document": "Articles of Organization (SOS Form 0074)", "filing_fee_usd": 100, "fee_notes": "$100; $25 surcharge if delivered in person for same-day filing. Credit-card filings (in person/online) carry a 4% service charge per SOS form.", "annual_report": {"name": "Annual Certificate", "fee_usd": 25, "frequency": "annual", "due": "Due on the anniversary date of formation; 60-day grace period before entity becomes inactive/not in good standing"}, "tax_notes": "Oklahoma franchise tax repealed for tax year 2024 and later (HB 1039X, 2023); LLCs not subject."}$j$::jsonb, $j${"document": "Certificate of Incorporation (for-profit)", "filing_fee_usd": 50, "fee_notes": "Minimum $50; fee is 1/10 of 1% of authorized capital stock (no-par shares valued at $50/share for fee computation).", "annual_report": {"name": "Annual Certificate (SOS fee table, 18 O.S. 1142)", "fee_usd": 10, "frequency": "annual", "due": "SOS FAQ: annual certificates due on formation anniversary with 60-day grace; SOS also states fully qualified corporations do not file an annual certificate with SOS and should consult the Oklahoma Tax Commission"}, "tax_notes": "Franchise tax (Form FRX-200) repealed effective tax year 2024 (HB 1039X); schedule of corporate officers still filed; foreign corporations still owe $100 registered agent fee."}$j$::jsonb, $j${"document": "Certificate of Incorporation (Oklahoma Not for Profit Corporation)", "filing_fee_usd": 25, "fee_notes": "$25 flat (18 O.S. 1142).", "annual_report": {"name": null, "fee_usd": null, "frequency": null, "due": null}, "tax_notes": "None identified."}$j$::jsonb, 'Every corporation/LLC must maintain a registered office (physical Okla