  ('OR', 'Oregon', 'Oregon Secretary of State - Corporation Division (Business Registry)', 'https://sos.oregon.gov/business/information-center/pages/starting-business.aspx', 'https://sos.oregon.gov/bizsearch', null, null, 'https://www.oregon.gov/dor/programs/businesses/pages/business-registration.aspx', $j${"document": "Articles of Organization", "filing_fee_usd": 100, "fee_notes": "$100 non-refundable processing fee.", "annual_report": {"name": "Annual Report", "fee_usd": 100, "frequency": "annual", "due": "Due on the anniversary of original filing; notice mailed ~45-50 days before"}, "tax_notes": "None identified at SOS level."}$j$::jsonb, $j${"document": "Articles of Incorporation (business corporation)", "filing_fee_usd": 100, "fee_notes": "$100 non-refundable processing fee.", "annual_report": {"name": "Annual Report", "fee_usd": 100, "frequency": "annual", "due": "Due on the anniversary of original filing"}, "tax_notes": "Not researched beyond SOS fees."}$j$::jsonb, $j${"document": "Articles of Incorporation - Nonprofit", "filing_fee_usd": 50, "fee_notes": "$50 non-refundable processing fee.", "annual_report": {"name": "Annual Report", "fee_usd": null, "frequency": "annual", "due": "Due on anniversary; administrative dissolution if not filed within 45 days of renewal date"}, "tax_notes": "Charitable nonprofits also report annually to Oregon DOJ Charitable Activities Section (fees not confirmed)."}$j$::jsonb, 'Registered agent required with an Oregon street address (no P.O. box, CMRA, mail-forwarding business or virtual office); agent may be an individual or an eligible entity (business corporation, LLC, professional corporation, nonprofit corporation).', $j$[{"url": "https://sos.oregon.gov/business/Documents/business-registry-forms/br-fee-schedule.pdf", "title": "Oregon SOS - Business Registry Fee Schedule"}, {"url": "https://sos.oregon.gov/business/documents/business-registry-forms/llc-articles.pdf", "title": "Oregon SOS - Articles of Organization (LLC)"}, {"