  ('PA', 'Pennsylvania', 'Pennsylvania Department of State - Bureau of Corporations and Charitable Organizations', 'https://www.pa.gov/agencies/dos/programs/business/fees-and-payments', 'https://file.dos.pa.gov/', 'https://file.dos.pa.gov/', 'https://business.pa.gov/register/registering-with-pennsylvania/basic-business-registration-overview/', 'https://www.pa.gov/services/revenue/register-my-business-for-taxes', $j${"document": "Certificate of Organization (Domestic LLC, DSCB:15-8821)", "filing_fee_usd": 125, "fee_notes": "$125 nonrefundable. Fee waived for qualifying veteran/reservist small businesses (Act 135 of 2016).", "annual_report": {"name": "Annual Report", "fee_usd": 7, "frequency": "annual", "due": "January 1 - September 30 each year, starting the year after formation; administrative dissolution for failure to file beginning with reports due in 2027 (six months after due date)"}, "tax_notes": "No state franchise tax identified for LLCs on official pages consulted."}$j$::jsonb, $j${"document": "Articles of Incorporation (For Profit, DSCB:15-1306)", "filing_fee_usd": 125, "fee_notes": "$125 nonrefundable.", "annual_report": {"name": "Annual Report", "fee_usd": 7, "frequency": "annual", "due": "January 1 - June 30 each year"}, "tax_notes": "Not researched beyond DOS fees."}$j$::jsonb, $j${"document": "Articles of Incorporation - Domestic Nonprofit (DSCB:15-5306/7102)", "filing_fee_usd": 125, "fee_notes": "$125 nonrefundable; no certificate of incorporation issued for nonprofits.", "annual_report": {"name": "Annual Report", "fee_usd": 0, "frequency": "annual", "due": "January 1 - June 30 each year"}, "tax_notes": "Nonprofits soliciting funds must separately register with the Bureau of Corporations and Charitable Organizations unless exempt."}$j$::jsonb, 'Must list a Pennsylvania registered office street address (P.O. box alone not acceptable) or name a Commercial Registered Office Provider (CROP) from the Department''s list plus county of venue.', $j$[{"url": 