  ('RI', 'Rhode Island', 'Rhode Island Department of State - Business Services Division', 'https://www.sos.ri.gov/divisions/business-services/business-basics/costs-and-fees', 'https://business.sos.ri.gov/corpweb/corpsearch/corpsearch.aspx', null, null, 'https://tax.ri.gov/', $j${"document": "Articles of Organization (Form 400)", "filing_fee_usd": 150, "fee_notes": "$150 (R.I.G.L. 7-16-6).", "annual_report": {"name": "Annual Report", "fee_usd": 50, "frequency": "annual", "due": "Between February 1 and May 1 each calendar year, excluding year of formation"}, "tax_notes": "$400 minimum annual charge to RI Division of Taxation (due March 15 for pass-through LLCs; April 15 for LLCs taxed as corporations)."}$j$::jsonb, $j${"document": "Articles of Incorporation (Form 100)", "filing_fee_usd": 230, "fee_notes": "Minimum $230 (form: corporations with fewer authorized shares than the form's threshold pay the $230 minimum; higher authorized shares cost more).", "annual_report": {"name": "Annual Report (Form 630)", "fee_usd": 50, "frequency": "annual", "due": "Between February 1 and May 1; late penalty (Form 630: additional $25; fee schedule shows $75 - conflict)"}, "tax_notes": "$400 minimum annual tax to RI Division of Taxation for corporations."}$j$::jsonb, $j${"document": "Articles of Incorporation - Non-Profit (Form 200)", "filing_fee_usd": 35, "fee_notes": "$35.", "annual_report": {"name": "Annual Report (Form 631)", "fee_usd": 20, "frequency": "annual", "due": "Between February 1 and May 1; additional $25 if not filed by May 31"}, "tax_notes": "Applicability of $400 minimum tax to nonprofits not confirmed."}$j$::jsonb, 'Registered agent must be a Rhode Island resident or qualified entity with a Rhode Island street address; P.O. boxes and virtual addresses not allowed.', $j$[{"url": "https://docs.sos.ri.gov/documents/BusinessServices/400-articles-of-organization.pdf", "title": "RI Form 400 - Articles of Organization (Rev. 03/2026)"}, {"url": "https://docs.sos.ri.gov/docum