  ('SD', 'South Dakota', 'South Dakota Secretary of State - Business Services', 'https://sdsos.gov/general-information/filing-fees.aspx', 'https://sosenterprise.sd.gov/businessservices/', 'https://sosenterprise.sd.gov/businessservices/', null, 'https://dor.sd.gov/businesses/taxes/', $j${"document": "Articles of Organization", "filing_fee_usd": 150, "fee_notes": "$150 filed electronically online; $165 on paper (includes $15 paper filing fee).", "annual_report": {"name": "Annual Report", "fee_usd": 55, "frequency": "annual", "due": "1st day of the anniversary month of initial filing; may file up to 2 months early; delinquent 2 months after due date; $55 late fee ($70 if filed on paper)"}, "tax_notes": "None identified."}$j$::jsonb, $j${"document": "Articles of Incorporation", "filing_fee_usd": 150, "fee_notes": "$150 online; $165 paper.", "annual_report": {"name": "Annual Report", "fee_usd": 55, "frequency": "annual", "due": "1st day of anniversary month; $70 on paper; $55 late fee"}, "tax_notes": "None identified."}$j$::jsonb, $j${"document": "Articles of Incorporation (Nonprofit)", "filing_fee_usd": 30, "fee_notes": "$30.", "annual_report": {"name": "Annual Report", "fee_usd": 10, "frequency": "annual", "due": "1st day of anniversary month; nonprofits exempt from the late fee but must still file"}, "tax_notes": "None identified."}$j$::jsonb, 'Registered agent must be a South Dakota resident with both a physical and mailing address in South Dakota (SOS FAQ); statute allows a noncommercial agent (may be an individual, including an owner), a commercial registered agent, or an office holder. Failure to maintain one is grounds for administrative dissolution.', $j$[{"url": "https://sdsos.gov/general-information/filing-fees.aspx", "title": "SD SOS - Filing Fees"}, {"url": "https://sdsos.gov/docs/business/llc-domestic-articlesoforganization.pdf", "title": "SD SOS - Domestic LLC Articles of Organization"}, {"url": "https://sdsos.gov/docs/business/nonprofitarticlesofincorporation20180215.pdf", "title": "SD SOS - Nonprofit Articles of Incorporation"}, {"url": "https://sdsos.gov/docs/business/nonprofitdomesticannualreport20240701.pdf", "title": "SD SOS - Annual Report for a Domestic Nonprofit Corporation"}, {"url": "https://sdsos.gov/Division%20of%20Business%20Services/FAQs/default.aspx", "title": "SD SOS - Business FAQs & Contact"}, {"url": "https://sosenterprise.sd.gov/businessservices/", "title": "SD SOS - Business Services (online)"}, {"url": "https://dor.sd.gov/businesses/taxes/", "title": "SD Department of Revenue - Business Tax"}]$j$::jsonb, $j$["Gathered from official-domain search results on 2026-11-27; confirm each figure on the official page before approving.", "Exact business-search page URL within sosenterprise.sd.gov not confirmed (portal root used).", "Late-fee figure conflict on older SOS pages ($50 vs current $55).", "No statewide general business license portal identified; business_license_url left null.", "Method caveat: this session's network policy blocked direct HTTP access to all state sites; facts were taken from search-index extracts of the official-domain pages listed in sources (search restricted to official domains), not from a live page load."]$j$::jsonb, '2026-11-27', '2027-05-27', 'draft'),
  ('TN', 'Tennessee', 'Tennessee Secretary of State - Division of Business and Charitable Organizations', 'https://sos.tn.gov/products/business-services/form-or-register-new-business', 'https://tnbear.tn.gov/Ecommerce/FilingSearch.aspx', 'https://tnbear.tn.gov/', null, 'https://www.tn.gov/revenue/taxes/franchise---excise-tax.html', $j${"document": "Articles of Organization (SS-4270)", "filing_fee_usd": 300, "fee_notes": "$50 per member, minimum $300, maximum $3,000. Online card convenience fee listed ($8.25 for LLC formation).", "annual_report": {"name": "Annual Report", "fee_usd": 300, "frequency": "annual", "due": "On or before the 1st day of the 4th month after fiscal year close (April 1 for calendar-year entities); fee $300 minimum, +$50 per member beyond six, max $3,000"}, "tax_notes": "Franchise & excise tax: register with TN Department of Revenue within 15 days (TNTAP); minimum franchise tax $100/year while registered with SOS, even if inactive; excise tax on net earnings."}$j$::jsonb, $j${"document": "Charter (For-Profit Corporation, SS-4417)", "filing_fee_usd": 100, "fee_notes": "$100.", "annual_report": {"name": "Annual Report", "fee_usd": 20, "frequency": "annual", "due": "1st day of 4th month after fiscal year close; +$20 if registered agent/office changed"}, "tax_notes": "Franchise & excise tax applies (minimum franchise tax $100)."}$j$::jsonb, $j${"document": "Charter (Nonprofit Corporation)", "filing_fee_usd": 100, "fee_notes": "$100 (certain school-related organizations exempt under T.C.A. 49-2-611).", "annual_report": {"name": "Annual Report", "fee_usd": 20, "frequency": "annual", "due": "1st day of 4th month after fiscal year close"}, "tax_notes": "F&E exemption for nonprofits not confirmed in this session."}$j$::jsonb, 'All entity types except general partnerships must maintain a registered agent and registered office in Tennessee; failure is grounds for administrative dissolution.', $j$[{"url": "https://sos.tn.gov/businesses/services/business-for