  ('TX', 'Texas', 'Texas Secretary of State - Business & Public Filings Division', 'https://www.sos.texas.gov/', 'https://direct.sos.state.tx.us/', 'https://direct.sos.state.tx.us/', null, 'https://comptroller.texas.gov/taxes/permit/', $j${"document": "Certificate of Formation - Limited Liability Company (Form 205)", "filing_fee_usd": 300, "fee_notes": "$300. Card payments carry a convenience fee ($0.25 + 2.25% per current Form 202 instructions; some forms state 2.7%).", "annual_report": {"name": "Texas Franchise Tax Report + Public Information Report (Comptroller)", "fee_usd": 0, "frequency": "annual", "due": "Annual (Comptroller); no tax due at or below $2.65 million revenue for 2026 reports, but Public Information Report/Ownership Information Report still required; No Tax Due Report discontinued from 2024"}, "tax_notes": "Texas franchise tax applies to LLCs (Comptroller)."}$j$::jsonb, $j${"document": "Certificate of Formation - For-Profit Corporation (Form 201)", "filing_fee_usd": 300, "fee_notes": "$300 (fee schedule item for Forms 201/203/205/206).", "annual_report": {"name": "Texas Franchise Tax Report + Public Information Report (Comptroller)", "fee_usd": 0, "frequency": "annual", "due": "Annual; same no-tax-due threshold ($2.65M for 2026)"}, "tax_notes": "Texas franchise tax applies."}$j$::jsonb, $j${"document": "Certificate of Formation - Nonprofit Corporation (Form 202)", "filing_fee_usd": 25, "fee_notes": "$25.", "annual_report": {"name": null, "fee_usd": null, "frequency": null, "due": null}, "tax_notes": "Franchise tax exemption for nonprofits not researched."}$j$::jsonb, 'Registered agent required: an individual Texas resident or a domestic/registered foreign entity (entity cannot be its own agent; SOS cannot serve). Registered office must be a physical Texas address where the agent can be served during business hours (P.O. box only in towns under 5,000 population). Agent must consent in writing/electronically.', $j$[{"url": "https://www.sos.state.tx.u