  ('VA', 'Virginia', 'Virginia State Corporation Commission - Office of the Clerk', 'https://www.scc.virginia.gov/businesses/new-business-resources/', 'https://cis.scc.virginia.gov/EntitySearch/Index', 'https://cis.scc.virginia.gov/', 'https://businessonestop.virginia.gov/starting.shtml', 'https://www.tax.virginia.gov/register-business-virginia', $j${"document": "Articles of Organization (Form LLC1011)", "filing_fee_usd": 100, "fee_notes": "$100 (Va. Code 13.1-1005).", "annual_report": {"name": "Annual Registration Fee", "fee_usd": 50, "frequency": "annual", "due": "By the last day of the month in which the LLC was formed, each year after formation; $25 late penalty; existence canceled if unpaid by last day of 3rd month after due date"}, "tax_notes": "No annual report for LLCs; annual registration fee only."}$j$::jsonb, $j${"document": "Articles of Incorporation (stock corporation)", "filing_fee_usd": 75, "fee_notes": "Minimum $75 = $25 filing fee + charter fee of $50 per 25,000 authorized shares or fraction (charter fee $2,500 if over 1,000,000 shares).", "annual_report": {"name": "Annual Report (no fee) + Annual Registration Fee", "fee_usd": 50, "frequency": "annual", "due": "Assessed ~2 months before and due by end of month of incorporation; fee $50 for up to 5,000 authorized shares, +$15 per additional 5,000 shares, max $850; penalty greater of 10% or $10"}, "tax_notes": "Annual registration fee based on authorized shares."}$j$::jsonb, $j${"document": "Articles of Incorporation (nonstock corporation, Form SCC819)", "filing_fee_usd": 75, "fee_notes": "$75 = $50 charter fee + $25 filing fee.", "annual_report": {"name": "Annual Report (no fee) + Annual Registration Fee", "fee_usd": 25, "frequency": "annual", "due": "Assessed on 1st day of 2nd month preceding incorporation month; due by end of incorporation month; $10 penalty"}, "tax_notes": "None identified."}$j$::jsonb, 'Must continuously maintain a Virginia registered office and agent. Individual agent must be a 